-- core_ui/internal/icons.lua
-- Icon registry and management system

local icons = {}\nlocal icon_configs = {}\n\nlocal function register_icon(id, texture, config)\n    if type(id) ~= \"string\" or id == \"\" or type(texture) ~= \"string\" then\n        return false\n    end\n    if icons[id] then\n        return false\n    end\n    icons[id] = texture\n    icon_configs[id] = config or {size = 32}\n    return true\nend\n\nlocal function get_icon(id)\n    return icons[id]\nend\n\nlocal function get_icon_texture(id)\n    return icons[id]\nend\n\nlocal function get_icon_config(id)\n    return icon_configs[id] or {size = 32}\nend\n\nlocal function all_icons()\n    local result = {}\n    for id, texture in pairs(icons) do\n        result[id] = {\n            texture = texture,\n            config = icon_configs[id],\n        }\n    end\n    return result\nend\n\nlocal function unregister_icon(id)\n    if type(id) ~= \"string\" or id == \"\" then\n        return false\n    end\n    if not icons[id] then\n        return false\n    end\n    icons[id] = nil\n    icon_configs[id] = nil\n    return true\nend\n\nreturn {\n    register_icon = register_icon,\n    get_icon = get_icon,\n    get_icon_texture = get_icon_texture,\n    get_icon_config = get_icon_config,\n    all_icons = all_icons,\n    unregister_icon = unregister_icon,\n}
